// ELEMENTS:
// 1. Fundo branco com o filete vermelho no topo
// 2. Eyebrow azul royal
// 3. Grelha 2×2 de cartões coloridos (cards "título: detalhe"), cada um com o seu ícone em traço,
//    a virar para a frente em sequência
// 4. Ícones de guardar e partilhar, frase (anim.text, **palavras** em Heavy) e marca (brand) em DM Mono
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const GREY = "#5A6370";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.6));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ICONS = [
  "M14 60 L60 20 L106 60 M26 50 V104 H94 V50 M50 104 V76 H70 V104",
  "M80 36 A30 30 0 1 0 80 84 M30 54 H72 M30 68 H66",
  "M8 106 H112 M22 106 V64 L50 40 L78 64 V106 M94 106 V16 M94 16 H58 M94 28 L106 16 M66 16 V36",
  "M14 44 L60 16 L106 44 Z M20 52 H100 M28 52 V96 M46 52 V96 M74 52 V96 M92 52 V96 M16 96 H104",
];
const CARDS = [
  { bg: BLUE, fg: WHITE, sub: "rgba(255,255,255,0.8)" },
  { bg: NAVY, fg: WHITE, sub: "rgba(255,255,255,0.8)" },
  { bg: RED, fg: WHITE, sub: "rgba(255,255,255,0.85)" },
  { bg: TINT, fg: NAVY, sub: GREY },
];

const ResumoCasos: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const brand = String(p.brand ?? "").trim();
  const cards = (Array.isArray(p.cards) ? (p.cards as unknown[]).map(String) : []).slice(0, 4).map((s) => {
    const i = s.indexOf(":");
    return i > 0 ? { title: s.slice(0, i).trim(), detail: s.slice(i + 1).trim() } : { title: s.trim(), detail: "" };
  });
  const parts = String(anim.text ?? "").split(/(\*\*[^*]+\*\*)/).filter(Boolean);

  const show = (delay: number, len = 0.5, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const close = 1.1;
  const stroke = { fill: "none", strokeWidth: 3.5, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, pathLength: 1, strokeDasharray: 1 };

  return (
    <AbsoluteFill style={{ backgroundColor: WHITE, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 44 * u, padding: `0 ${70 * u}px` }}>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: BLUE, opacity: show(0) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 22 * u, width: "100%", perspective: 1600 * u }}>
          {cards.map((c, i) => {
            const k = show(0.05 + i * 0.12, 0.55, BACK);
            const col = CARDS[i % 4];
            return (
              <div key={i} style={{ background: col.bg, borderRadius: 26 * u, padding: `${30 * u}px ${30 * u}px`, height: 300 * u, boxSizing: "border-box", display: "flex", flexDirection: "column", justifyContent: "space-between", transform: `rotateY(${(1 - k) * 80}deg)`, opacity: Math.min(1, k * 2), boxShadow: "0 18px 40px rgba(0,31,68,0.18)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                  <svg width={80 * u} height={80 * u} viewBox="0 0 120 120"><path d={ICONS[i % 4]} stroke={col.fg} {...stroke} strokeDashoffset={1 - show(0.3 + i * 0.12, 0.7)} /></svg>
                  <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 60 * u, color: col.fg, opacity: 0.35, lineHeight: 1 }}>{i + 1}</div>
                </div>
                <div>
                  <div style={{ fontFamily: FONTS.display, fontWeight: 700, fontSize: 44 * u, lineHeight: 1.05, color: col.fg }}>{c.title}</div>
                  {c.detail ? <div style={{ fontFamily: FONTS.body, fontWeight: 500, fontSize: 28 * u, color: col.sub, marginTop: 8 * u }}>{c.detail}</div> : null}
                </div>
              </div>
            );
          })}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 36 * u, marginTop: 20 * u, opacity: show(close), transform: `translateY(${(1 - show(close)) * 24 * u}px)` }}>
          <svg width={96 * u} height={96 * u} viewBox="0 0 120 120"><path d="M34 14 H86 V106 L60 86 L34 106 Z" stroke={NAVY} {...stroke} strokeDashoffset={1 - show(close, 0.8)} /></svg>
          <div style={{ fontFamily: FONTS.display, fontSize: 76 * u, lineHeight: 1, color: NAVY, whiteSpace: "nowrap" }}>
            {parts.map((s, i) => <span key={i} style={{ fontWeight: s.startsWith("**") ? 800 : 300 }}>{s.replace(/\*\*/g, "")}</span>)}
          </div>
          <svg width={96 * u} height={96 * u} viewBox="0 0 120 120">
            <path d="M40 54 L80 30 M40 66 L80 90" stroke={NAVY} {...stroke} strokeDashoffset={1 - show(close + 0.2, 0.6)} />
            <circle cx={30} cy={60} r={12} fill={RED} />
            <circle cx={88} cy={26} r={12} fill="none" stroke={NAVY} strokeWidth={3.5} />
            <circle cx={88} cy={94} r={12} fill="none" stroke={NAVY} strokeWidth={3.5} />
          </svg>
        </div>
        {brand ? <div style={{ fontFamily: FONTS.mono, fontSize: 30 * u, letterSpacing: "0.3em", color: NAVY, opacity: show(close + 0.6) }}>{brand}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
    </AbsoluteFill>
  );
};

export default ResumoCasos;
